SELECT t.id AS "Id do Tenant", t.name AS "Nome do Tenant", COUNT(tu.userid) AS "Total de usuários por tenant" FROM mdl_tool_tenant AS t LEFT JOIN mdl_tool_tenant_user AS tu ON t.id = tu.tenantid LEFT JOIN mdl_user AS u ON u.id = tu.userid WHERE u.deleted = 0 GROUP BY t.id, t.name UNION ALL SELECT NULL AS "Id do Tenant", 'Total Geral' AS "Nome do Tenant", COUNT(*) AS "Total de usuários por tenant" FROM mdl_user WHERE deleted = 0;
